import React, { useState, useEffect, useRef } from 'react';
import './App.css';

function App() {
  const [messages, setMessages] = useState([]);
  const [inputMessage, setInputMessage] = useState('');
  const [feedbackText, setFeedbackText] = useState(''); // ✅ เพิ่ม state สำหรับ feedback
  const [role, setRole] = useState('Frontend Developer');
  const messagesEndRef = useRef(null);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSubmit = async (event) => {
    event.preventDefault();
    if (!inputMessage.trim()) return;

    addMessage(inputMessage, 'user');

    try {
      const response = await fetch('http://localhost:4001/api/chat', {
        // ✅ เปลี่ยนเป็น AI backend
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: inputMessage, role }),
      });

      const data = await response.json();
      addMessage(data.response || 'No response from server.', 'bot');
    } catch (error) {
      console.error('Error:', error);
      addMessage('Error: Unable to communicate with the server.', 'bot');
    }

    setInputMessage('');
  };

  const handleWrapUp = async () => {
    try {
      const response = await fetch('http://localhost:4001/api/chat', {
        // ✅ ใช้ AI backend
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: '__WRAP_UP__', role }),
      });

      const data = await response.json();
      addMessage(data.response || 'No response from server.', 'bot');
    } catch (error) {
      console.error('Error:', error);
      addMessage('Error: Could not finish the interview.', 'bot');
    }
  };

  const handleFeedback = async () => {
    if (!inputMessage.trim()) return;
  
    try {
      const response = await fetch('http://localhost:3000/api/feedback', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ feedback: inputMessage, role }),
      });
  
      const data = await response.json();  // ← error น่าจะอยู่ตรงนี้
      console.log("✅ Feedback response:", data);
      addMessage("Feedback saved successfully!", "bot");
    } catch (error) {
      console.error('Error sending feedback:', error);
      addMessage('Error: Unable to send feedback.', 'bot');
    }
  
    setInputMessage('');
  };
  

  const addMessage = (text, sender) => {
    setMessages((prev) => [...prev, { text, sender }]);
  };

  return (
    <div className="App">
      <div className="chat-window">
        <h2>Mock Interview Chatbot</h2>
        <select value={role} onChange={(e) => setRole(e.target.value)}>
          <option value="Frontend Developer">Frontend Developer</option>
          <option value="Backend Developer">Backend Developer</option>
          <option value="Data Scientist">Data Scientist</option>
          <option value="UX Designer">UX Designer</option>
        </select>

        <ul className="messages-list">
          {messages.map((msg, i) => (
            <li key={i} className={`message ${msg.sender}`}>
              {msg.text}
            </li>
          ))}
          <div ref={messagesEndRef} />
        </ul>

        <form onSubmit={handleSubmit} className="input-area">
          <input
            type="text"
            value={inputMessage}
            onChange={(e) => setInputMessage(e.target.value)}
            placeholder="Your response..."
          />
          <button type="submit">Send</button>
          <button type="button" onClick={handleWrapUp} className="wrap-up-button">Finish Interview</button>
        </form>
      </div>

      <div className='feedback'>
        <h3>Feedback</h3>
        <input
          type="text"
          value={feedbackText}
          onChange={(e) => setFeedbackText(e.target.value)}
          placeholder="Your feedback..."
        />
        <button onClick={handleFeedback} className="wrap-up-button">Submit Feedback</button>
      </div>
    </div>
  );
}

export default App;
